-- Demo only: real state legislation (verified via web research) replaces
-- NYC bills that had been simulated into other states. Guarded.
do $$ begin
  if to_regclass('public.simulated_environment') is null then
    raise exception 'refusing: not the simulated environment';
  end if;
end $$;

drop table if exists public.demo_state_bills;
create table public.demo_state_bills (st text, id text, title text);

on conflict (id) do update set title = excluded.title,
  plain_summary = excluded.plain_summary, chamber = excluded.chamber,
  status = excluded.status, topic_category = excluded.topic_category;



-- Reassign simulated state responses from NYC bills to that state's own
-- bills: each voter keeps at most one rating per state bill, extras drop.
with cand as (
  select w.user_id, w.item_id, split_part(w.district_id, '-', 1) as st,
         row_number() over (partition by w.user_id order by w.item_id) - 1 as rn
  from public.weigh_ins w
  where w.kind = 'bill'
    and split_part(w.district_id, '-', 1) not in ('nyc', 'us')
    and w.item_id like 'nyc-%'
),
b as (
  select st, id, title,
         row_number() over (partition by st order by id) - 1 as rn,
         count(*) over (partition by st) as cnt
  from public.demo_state_bills
)
delete from public.weigh_ins w
using cand c
left join b on b.st = c.st and b.rn = c.rn
where w.user_id = c.user_id and w.kind = 'bill' and w.item_id = c.item_id
  and b.id is null;

with cand as (
  select w.user_id, w.item_id, split_part(w.district_id, '-', 1) as st,
         row_number() over (partition by w.user_id order by w.item_id) - 1 as rn
  from public.weigh_ins w
  where w.kind = 'bill'
    and split_part(w.district_id, '-', 1) not in ('nyc', 'us')
    and w.item_id like 'nyc-%'
),
b as (
  select st, id, title,
         row_number() over (partition by st order by id) - 1 as rn,
         count(*) over (partition by st) as cnt
  from public.demo_state_bills
)
update public.weigh_ins w
set item_id = b.id, title = b.title
from cand c
join b on b.st = c.st and b.rn = c.rn
where w.user_id = c.user_id and w.kind = 'bill' and w.item_id = c.item_id;
